def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(comp) == 1:
                y, x = comp[0]
                neighbors = [(y+dy, x+dx) for dy, dx in ((1,0),(-1,0),(0,1),(0,-1))
                             if 0 <= y+dy < h and 0 <= x+dx < w]
                # Restore a covered object pixel when nearby cells agree; otherwise erase the speck.
                counts = {}
                for ny, nx in neighbors:
                    v = grid[ny][nx]
                    if v != color and v != bg:
                        counts[v] = counts.get(v, 0) + 1
                out[y][x] = max(counts, key=counts.get) if counts and max(counts.values()) >= 2 else bg
    return out
